-- 검증(읽기 전용): ap_environmental_science. ok 가 모두 true 여야 한다.
select 'subject' as check, 1 as expected, (select count(*) from subjects where ap_subject_code = 'ap_environmental_science') as actual, 1 = (select count(*) from subjects where ap_subject_code = 'ap_environmental_science') as ok
union all
select 'edition' as check, 1 as expected, (select count(*) from ap_curriculum_editions where subject_id = (select id from subjects where ap_subject_code = 'ap_environmental_science') and edition = 'ced-2027') as actual, 1 = (select count(*) from ap_curriculum_editions where subject_id = (select id from subjects where ap_subject_code = 'ap_environmental_science') and edition = 'ced-2027') as ok
union all
select 'skills' as check, 7 as expected, (select count(*) from ap_skills where subject_id = (select id from subjects where ap_subject_code = 'ap_environmental_science') and edition = 'ced-2027') as actual, 7 = (select count(*) from ap_skills where subject_id = (select id from subjects where ap_subject_code = 'ap_environmental_science') and edition = 'ced-2027') as ok
union all
select 'weights' as check, 9 as expected, (select count(*) from ap_exam_weights where subject_id = (select id from subjects where ap_subject_code = 'ap_environmental_science') and edition = 'ced-2027') as actual, 9 = (select count(*) from ap_exam_weights where subject_id = (select id from subjects where ap_subject_code = 'ap_environmental_science') and edition = 'ced-2027') as ok
union all
select 'folders(units)' as check, 9 as expected, (select count(*) from subject_keyword_folders where subject_id = (select id from subjects where ap_subject_code = 'ap_environmental_science') and official_code in ('1','2','3','4','5','6','7','8','9')) as actual, 9 = (select count(*) from subject_keyword_folders where subject_id = (select id from subjects where ap_subject_code = 'ap_environmental_science') and official_code in ('1','2','3','4','5','6','7','8','9')) as ok
